1	package clinical
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// ---- 测试基础设施 ----
10	
11	type fakeClock struct{ t time.Time }
12	
13	func newTestStore(t *testing.T) (*Store, *fakeClock) {
14		t.Helper()
15		clk := &fakeClock{t: time.Date(2026, 1, 1, 9, 0, 0, 0, time.UTC)}
16		dir := t.TempDir()
17		s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
18		if err != nil {
19			t.Fatalf("open: %v", err)
20		}
21		t.Cleanup(func() { _ = s.Close() })
22		return s, clk
23	}
24	
25	var (
26		doc  = InternalActor("doc-1")
27		doc2 = InternalActor("doc-2")
28		rcv  = ReceiverActor("rcv-a")
29		rcvB = ReceiverActor("rcv-b")
30	)
31	
32	func setupPatientEncounter(t *testing.T, s *Store) (ID, ID) {
33		t.Helper()
34		p, err := s.RegisterPatient(doc, "合成患者甲")
35		if err != nil {
36			t.Fatalf("register patient: %v", err)
37		}
38		e, err := s.AddEncounter(doc, p.ID, time.Time{})
39		if err != nil {
40			t.Fatalf("add encounter: %v", err)
41		}
42		return p.ID, e.ID
43	}
44	
45	func countRecords(s *Store) int {
46		c := 0
47		_ = s.view(func(snap *snapshot) error { c = len(snap.Records); return nil })
48		return c
49	}
50	
51	func auditActions(events []AuditEvent) map[string]int {
52		m := map[string]int{}
53		for _, e := range events {
54			m[e.Action]++
55		}
56		return m
57	}
58	
59	// ---- 基线行为保留 ----
60	
61	func TestReadyStillTrue(t *testing.T) {
62		if !Ready() {
63			t.Fatal("Ready must remain true")
64		}
65	}
66	
67	// ---- 患者与就诊 ----
68	
69	func TestRegisterPatientIsSyntheticAndStableID(t *testing.T) {
70		s, _ := newTestStore(t)
71		p, err := s.RegisterPatient(doc, "合成患者甲")
72		if err != nil {
73			t.Fatalf("register: %v", err)
74		}
75		if p.ID == "" {
76			t.Fatal("patient id empty")
77		}
78		if p.Source != SyntheticSource {
79			t.Fatalf("source = %q, want %q", p.Source, SyntheticSource)
80		}
81		got, err := s.GetPatient(doc, p.ID)
82		if err != nil {
83			t.Fatalf("get: %v", err)
84		}
85		if got.ID != p.ID {
86			t.Fatalf("id not stable: %q vs %q", got.ID, p.ID)
87		}
88	}
89	
90	func TestRegisterPatientRequiresInternal(t *testing.T) {
91		s, _ := newTestStore(t)
92		if _, err := s.RegisterPatient(rcv, "x"); !errors.Is(err, ErrAccessDenied) {
93			t.Fatalf("receiver register err = %v, want ErrAccessDenied", err)
94		}
95		if _, err := s.RegisterPatient(InternalActor(""), "x"); !errors.Is(err, ErrAccessDenied) {
96			t.Fatalf("empty actor err = %v", err)
97		}
98		if _, err := s.RegisterPatient(doc, ""); !errors.Is(err, ErrInvalidArgument) {
99			t.Fatalf("empty name err = %v", err)
100		}
101	}
102	
103	func TestAddEncounterValidation(t *testing.T) {
104		s, _ := newTestStore(t)
105		pid, _ := setupPatientEncounter(t, s)
106	
107		if _, err := s.AddEncounter(doc, "pat_missing", time.Time{}); !errors.Is(err, ErrNotFound) {
108			t.Fatalf("missing patient err = %v, want ErrNotFound", err)
109		}
110	
111		other, err := s.RegisterPatient(doc, "合成患者乙")
112		if err != nil {
113			t.Fatal(err)
114		}
115		// 手工构造“其他患者的就诊 id”直接作为引用：通过第二患者的真实就诊验证。
116		encOther, err := s.AddEncounter(doc, other.ID, time.Time{})
117		if err != nil {
118			t.Fatal(err)
119		}
120		// 在草稿上跨患者引用就诊。
121		if _, err := s.CreateDraft(doc, pid, encOther.ID, Diagnosis, "x"); !errors.Is(err, ErrMismatchedPatient) {
122			t.Fatalf("cross-patient encounter err = %v, want ErrMismatchedPatient", err)
123		}
124	}
125	
126	// ---- 草稿生命周期 ----
127	
128	func TestDraftCRUDAndFailureLeavesNothing(t *testing.T) {
129		s, _ := newTestStore(t)
130		pid, eid := setupPatientEncounter(t, s)
131	
132		before := countRecords(s)
133		if _, err := s.CreateDraft(doc, pid, "enc_missing", Diagnosis, "高血压"); !errors.Is(err, ErrNotFound) {
134			t.Fatalf("missing encounter err = %v", err)
135		}
136		if countRecords(s) != before {
137			t.Fatal("failed create left a record")
138		}
139		if _, err := s.CreateDraft(doc, pid, eid, "bogus", "x"); !errors.Is(err, ErrInvalidArgument) {
140			t.Fatalf("bad category err = %v", err)
141		}
142		if _, err := s.CreateDraft(doc, pid, eid, Diagnosis, "   "); !errors.Is(err, ErrInvalidArgument) {
143			t.Fatalf("blank content err = %v", err)
144		}
145	
146		r, err := s.CreateDraft(doc, pid, eid, Diagnosis, "高血压 I10")
147		if err != nil {
148			t.Fatalf("create draft: %v", err)
149		}
150		if _, err := s.UpdateDraft(doc, r.ID, "高血压 I10（修订）"); err != nil {
151			t.Fatalf("update draft: %v", err)
152		}
153		if err := s.DeleteDraft(doc, r.ID); err != nil {
154			t.Fatalf("delete draft: %v", err)
155		}
156		if _, err := s.UpdateDraft(doc, r.ID, "x"); !errors.Is(err, ErrNotFound) {
157			t.Fatalf("update deleted draft err = %v", err)
158		}
159	}
160	
161	func TestActivationSnapshotsContentAndTime(t *testing.T) {
162		s, clk := newTestStore(t)
163		pid, eid := setupPatientEncounter(t, s)
164	
165		r, err := s.CreateDraft(doc, pid, eid, Order, "阿司匹林 100mg")
166		if err != nil {
167			t.Fatal(err)
168		}
169		clk.t = clk.t.Add(2 * time.Hour)
170		v, err := s.ActivateRecord(doc, r.ID)
171		if err != nil {
172			t.Fatalf("activate: %v", err)
173		}
174		if v.Number != 1 || v.Content != "阿司匹林 100mg" {
175			t.Fatalf("unexpected v1: %+v", v)
176		}
177		if !v.CreatedAt.Equal(clk.t) {
178			t.Fatalf("effective time %v != %v", v.CreatedAt, clk.t)
179		}
180	
181		// 生效后不能按草稿方式覆盖或删除。
182		if _, err := s.UpdateDraft(doc, r.ID, "覆盖"); !errors.Is(err, ErrActive) {
183			t.Fatalf("update active err = %v, want ErrActive", err)
184		}
185		if err := s.DeleteDraft(doc, r.ID); !errors.Is(err, ErrActive) {
186			t.Fatalf("delete active err = %v, want ErrActive", err)
187		}
188		// 重复生效也被拒绝。
189		if _, err := s.ActivateRecord(doc, r.ID); !errors.Is(err, ErrActive) {
190			t.Fatalf("re-activate err = %v, want ErrActive", err)
191		}
192	}
193	
194	func TestCorrectionVersionChainAndConflict(t *testing.T) {
195		s, clk := newTestStore(t)
196		pid, eid := setupPatientEncounter(t, s)
197		r, _ := s.CreateDraft(doc, pid, eid, Diagnosis, "旧诊断")
198		v1, err := s.ActivateRecord(doc, r.ID)
199		if err != nil {
200			t.Fatal(err)
201		}
202	
203		// 缺原因、非法版本号。
204		if _, err := s.CorrectRecord(doc, r.ID, 1, "新诊断", "  "); !errors.Is(err, ErrInvalidArgument) {
205			t.Fatalf("blank reason err = %v", err)
206		}
207		if _, err := s.CorrectRecord(doc, r.ID, 0, "新诊断", "原因"); !errors.Is(err, ErrInvalidArgument) {
208			t.Fatalf("zero version err = %v", err)
209		}
210	
211		clk.t = clk.t.Add(time.Hour)
212		v2, err := s.CorrectRecord(doc, r.ID, 1, "新诊断", "录入笔误")
213		if err != nil {
214			t.Fatalf("correct: %v", err)
215		}
216		if v2.Number != 2 || v2.PrevID != v1.ID || v2.Reason != "录入笔误" {
217			t.Fatalf("bad v2: %+v", v2)
218		}
219		if !v2.CreatedAt.Equal(clk.t) {
220			t.Fatalf("correction time %v != %v", v2.CreatedAt, clk.t)
221		}
222	
223		// v1 内容与原因原样保留。
224		chart, err := s.Chart(doc, pid)
225		if err != nil {
226			t.Fatal(err)
227		}
228		var hist *RecordHistory
229		for i := range chart.Records {
230			if chart.Records[i].Record.ID == r.ID {
231				hist = &chart.Records[i]
